import os
import json
from typing import Any, Dict, Optional
import requests


class FederatedLoginError(Exception):
    pass


def _normalize_claims(raw: Dict[str, Any]) -> Dict[str, Any]:
    def first_value(value: Any) -> Any:
        if isinstance(value, list):
            return value[0] if value else None
        return value

    normalized = {
        "subject": raw.get("sub") or raw.get("subject"),
        "issuer": raw.get("iss") or raw.get("issuer"),
        "email": raw.get("email"),
        "email_verified": raw.get("email_verified"),
        "name": raw.get("name") or raw.get("given_name") or raw.get("preferred_username"),
        "given_name": raw.get("given_name"),
        "family_name": raw.get("family_name"),
        "preferred_username": raw.get("preferred_username"),
        "picture": raw.get("picture"),
        "locale": raw.get("locale"),
        "groups": raw.get("groups"),
        "roles": raw.get("roles"),
        "raw_claims": raw,
    }

    normalized["email"] = first_value(normalized["email"])
    normalized["groups"] = first_value(normalized["groups"])
    normalized["roles"] = first_value(normalized["roles"])
    return normalized


def fetch_and_normalize_federated_user_profile(
    access_token: str,
    userinfo_url: Optional[str] = None,
    timeout: float = 10.0,
) -> Dict[str, Any]:
    """
    Fetch and normalize federated user profile claims using IBM Cloud App ID userinfo endpoint.
    """
    if not access_token:
        raise FederatedLoginError("access_token is required")

    base_url = userinfo_url or os.getenv("IBM_APPID_USERINFO_URL")
    if not base_url:
        raise FederatedLoginError(
            "userinfo_url is required (or set IBM_APPID_USERINFO_URL)"
        )

    headers = {
        "Authorization": f"Bearer {access_token}",
        "Accept": "application/json",
    }

    resp = requests.get(base_url, headers=headers, timeout=timeout)
    if resp.status_code >= 400:
        try:
            detail = resp.json()
        except Exception:
            detail = resp.text
        raise FederatedLoginError(f"userinfo request failed: {resp.status_code} {detail}")

    try:
        raw_claims = resp.json()
    except Exception as exc:
        raise FederatedLoginError("userinfo response was not valid JSON") from exc

    if not isinstance(raw_claims, dict):
        raise FederatedLoginError("userinfo response JSON must be an object")

    return _normalize_claims(raw_claims)


def exchange_authorization_code_for_claims(
    code: str,
    redirect_uri: str,
    token_url: Optional[str] = None,
    client_id: Optional[str] = None,
    client_secret: Optional[str] = None,
    scope: str = "openid profile email",
    timeout: float = 10.0,
) -> Dict[str, Any]:
    """
    Optional helper for IBM Cloud App ID OIDC flow:
    exchanges authorization code for an access token and fetches normalized claims.
    """
    if not code:
        raise FederatedLoginError("code is required")
    if not redirect_uri:
        raise FederatedLoginError("redirect_uri is required")

    token_endpoint = token_url or os.getenv("IBM_APPID_TOKEN_URL")
    if not token_endpoint:
        raise FederatedLoginError("token_url is required (or set IBM_APPID_TOKEN_URL)")

    client_id = client_id or os.getenv("IBM_APPID_CLIENT_ID")
    client_secret = client_secret or os.getenv("IBM_APPID_CLIENT_SECRET")

    if not client_id or not client_secret:
        raise FederatedLoginError(
            "client_id and client_secret are required (or set IBM_APPID_CLIENT_ID / IBM_APPID_CLIENT_SECRET)"
        )

    data = {
        "grant_type": "authorization_code",
        "code": code,
        "redirect_uri": redirect_uri,
        "scope": scope,
    }

    resp = requests.post(
        token_endpoint,
        data=data,
        auth=(client_id, client_secret),
        headers={"Accept": "application/json"},
        timeout=timeout,
    )

    if resp.status_code >= 400:
        try:
            detail = resp.json()
        except Exception:
            detail = resp.text
        raise FederatedLoginError(f"token request failed: {resp.status_code} {detail}")

    try:
        token_payload = resp.json()
    except Exception as exc:
        raise FederatedLoginError("token response was not valid JSON") from exc

    access_token = token_payload.get("access_token")
    if not access_token:
        raise FederatedLoginError("token response missing access_token")

    userinfo_url = os.getenv("IBM_APPID_USERINFO_URL")
    return fetch_and_normalize_federated_user_profile(
        access_token=access_token,
        userinfo_url=userinfo_url,
        timeout=timeout,
    )
